'use client';

import { useId, useRef, useState } from 'react';
import type { KeyboardEvent } from 'react';
import './searchable-faq.css';

export interface SearchableFAQItem {
  id: string;
  question: string;
  answer: string;
  category?: string;
  keywords?: string[];
}

export interface SearchableFAQProps {
  items: SearchableFAQItem[];
  title?: string;
  searchPlaceholder?: string;
  defaultOpenId?: string;
  onOpenChange?: (id: string | null) => void;
  className?: string;
}

/** Searchable, categorized answers. Filtering closes the currently open answer. */
export function SearchableFAQ({ items, title = 'Questions & answers', searchPlaceholder = 'Search questions…', defaultOpenId, onOpenChange, className = '' }: SearchableFAQProps) {
  const uid = useId();
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<string | null>(null);
  const [openId, setOpenId] = useState<string | null>(defaultOpenId ?? null);
  const search = useRef<HTMLInputElement>(null);
  const triggers = useRef(new Map<string, HTMLButtonElement>());
  const groups = Array.from(new Set(items.flatMap(item => item.category ? [item.category] : [])));
  const activeCategory = category && groups.includes(category) ? category : null;
  const term = query.trim().toLocaleLowerCase();
  const visible = items.filter(item => (!activeCategory || item.category === activeCategory) && `${item.question} ${item.answer} ${(item.keywords ?? []).join(' ')}`.toLocaleLowerCase().includes(term));
  const activeOpenId = visible.some(item => item.id === openId) ? openId : null;

  function closeAnswer() {
    setOpenId(null);
    if (activeOpenId !== null) onOpenChange?.(null);
  }

  function reset() {
    setQuery('');
    setCategory(null);
    closeAnswer();
    search.current?.focus();
  }

  function navigate(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let next: number;
    if (event.key === 'ArrowDown') next = (index + 1) % visible.length;
    else if (event.key === 'ArrowUp') next = (index - 1 + visible.length) % visible.length;
    else if (event.key === 'Home') next = 0;
    else if (event.key === 'End') next = visible.length - 1;
    else return;
    event.preventDefault();
    triggers.current.get(visible[next].id)?.focus();
  }

  return <section className={`ac-faq ${className}`} aria-labelledby={title ? `${uid}-title` : undefined} aria-label={title ? undefined : 'Questions and answers'}>
    <div className="ac-faq-layout">
      <div className="ac-faq-tools">
        {title && <h2 id={`${uid}-title`} className="ac-faq-title">{title}</h2>}
        <label className="ac-faq-search" htmlFor={`${uid}-search`}>
          <svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/></svg>
          <span className="ac-faq-sr-only">Search questions and answers</span>
          <input ref={search} id={`${uid}-search`} type="search" placeholder={searchPlaceholder} value={query} onChange={event => { setQuery(event.target.value); closeAnswer(); }}/>
        </label>
        {groups.length > 0 && <div className="ac-faq-categories" role="group" aria-label="Question categories">
          <button type="button" aria-pressed={activeCategory === null} onClick={() => { setCategory(null); closeAnswer(); }}>All</button>
          {groups.map(group => <button key={group} type="button" aria-pressed={activeCategory === group} onClick={() => { setCategory(group); closeAnswer(); }}>{group}</button>)}
        </div>}
        <p className="ac-faq-count" role="status">{visible.length} {visible.length === 1 ? 'question' : 'questions'}{term || activeCategory ? ` of ${items.length}` : ''}</p>
      </div>
      <div className="ac-faq-results">
        {visible.map((item, index) => {
          const expanded = activeOpenId === item.id;
          const position = items.indexOf(item);
          return <div key={item.id} className="ac-faq-item" data-open={expanded}>
            <h3 className="ac-faq-question"><button type="button" id={`${uid}-question-${position}`} ref={element => { if (element) triggers.current.set(item.id, element); else triggers.current.delete(item.id); }} aria-expanded={expanded} aria-controls={`${uid}-answer-${position}`} onKeyDown={event => navigate(event, index)} onClick={() => { const next = expanded ? null : item.id; setOpenId(next); onOpenChange?.(next); }}>
              <span className="ac-faq-number" aria-hidden="true">{String(position + 1).padStart(2, '0')}</span>
              <span>{item.question}</span>
              <span className="ac-faq-toggle" aria-hidden="true"><svg viewBox="0 0 20 20" fill="none"><path d="M4 10h12"/><path className="ac-faq-plus" d="M10 4v12"/></svg></span>
            </button></h3>
            <div className="ac-faq-answer" id={`${uid}-answer-${position}`} role="region" aria-labelledby={`${uid}-question-${position}`} hidden={!expanded}><p>{item.answer}</p></div>
          </div>;
        })}
        {visible.length === 0 && <div className="ac-faq-empty"><p>{items.length ? 'No matching questions.' : 'No questions yet.'}</p>{items.length > 0 && <button type="button" onClick={reset}>Clear filters <span aria-hidden="true">↗</span></button>}</div>}
      </div>
    </div>
  </section>;
}

.ac-faq { --ac-faq-ink:#262d28; --ac-faq-muted:#686e66; --ac-faq-line:#262d2829; --ac-faq-surface:#f5f4ed; --ac-faq-accent:#97432e; container-type:inline-size; width:100%; min-width:0; color:var(--ac-faq-ink); font-family:Arial,Helvetica,sans-serif; }
.ac-faq *, .ac-faq *::before, .ac-faq *::after { box-sizing:border-box; }
.ac-faq-layout { display:grid; grid-template-columns:minmax(180px,.8fr) minmax(0,1.7fr); gap:clamp(32px,6cqi,90px); }
.ac-faq-tools { min-width:0; }
.ac-faq-title { margin:0 0 26px; font-family:Georgia,'Times New Roman',serif; font-weight:400; font-size:clamp(32px,4.6cqi,56px); line-height:1.04; letter-spacing:-.045em; text-wrap:balance; }
.ac-faq-search { display:flex; align-items:center; gap:10px; border:1px solid var(--ac-faq-line); border-radius:5px; padding:0 13px; background:var(--ac-faq-surface); }
.ac-faq-search:focus-within { outline:2px solid var(--ac-faq-accent); outline-offset:3px; }
.ac-faq-search svg { width:16px; height:16px; flex-shrink:0; stroke:currentColor; stroke-width:1.4; }
.ac-faq-search input { font:inherit; font-size:13px; width:100%; min-width:0; height:46px; padding:0; border:0; background:transparent; color:inherit; outline:none; }
.ac-faq-search input::placeholder { color:var(--ac-faq-muted); opacity:1; }
.ac-faq-categories { display:flex; flex-wrap:wrap; gap:7px; margin-top:16px; }
.ac-faq button { font:inherit; color:inherit; cursor:pointer; }
.ac-faq-categories button { border:1px solid var(--ac-faq-line); border-radius:999px; background:transparent; font-size:11px; line-height:1.4; padding:7px 12px; min-height:34px; }
.ac-faq-categories button[aria-pressed=true] { background:var(--ac-faq-ink); color:var(--ac-faq-surface); border-color:var(--ac-faq-ink); }
.ac-faq button:focus-visible { outline:2px solid var(--ac-faq-accent); outline-offset:4px; }
.ac-faq-count { margin:22px 0 0; color:var(--ac-faq-muted); font-size:11px; line-height:1.5; }
.ac-faq-results { min-width:0; border-top:1px solid var(--ac-faq-line); }
.ac-faq-item { border-bottom:1px solid var(--ac-faq-line); }
.ac-faq-question { margin:0; font-size:inherit; font-weight:400; }
.ac-faq-question button { display:grid; grid-template-columns:28px minmax(0,1fr) 30px; gap:16px; align-items:center; text-align:left; width:100%; min-height:76px; padding:20px 0; background:transparent; border:0; font-size:clamp(16px,2cqi,22px); line-height:1.35; letter-spacing:-.025em; }
.ac-faq-number { color:var(--ac-faq-muted); font-family:monospace; font-size:10px; letter-spacing:0; }
.ac-faq-toggle { display:grid; place-items:center; width:30px; height:30px; border:1px solid var(--ac-faq-line); border-radius:50%; transition:background .18s,color .18s; }
.ac-faq-toggle svg { width:16px; height:16px; stroke:currentColor; stroke-width:1.3; }
.ac-faq-plus { transform-origin:50% 50%; transition:transform .18s; }
.ac-faq-item[data-open=true] .ac-faq-toggle { color:var(--ac-faq-surface); background:var(--ac-faq-ink); }
.ac-faq-item[data-open=true] .ac-faq-plus { transform:scaleY(0); }
.ac-faq-answer:not([hidden]) { animation:ac-faq-enter .18s ease-out; }
.ac-faq-answer p { margin:0; padding:0 46px 24px 44px; color:var(--ac-faq-muted); font-size:14px; line-height:1.7; white-space:pre-line; overflow-wrap:anywhere; }
.ac-faq-empty { padding:35px 0; }
.ac-faq-empty p { margin:0 0 16px; font-size:17px; }
.ac-faq-empty button { padding:8px 0; background:transparent; border:0; border-bottom:1px solid currentColor; font-size:13px; }
.ac-faq-empty button span { margin-left:20px; }
.ac-faq-sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
@keyframes ac-faq-enter { from { opacity:0; transform:translateY(-4px); } to { opacity:1; transform:translateY(0); } }
@container (max-width:720px) { .ac-faq-layout { grid-template-columns:minmax(0,1fr); gap:24px; } .ac-faq-title { font-size:clamp(30px,6cqi,44px); margin-bottom:18px; } .ac-faq-count { margin-top:14px; } .ac-faq-question button { min-height:65px; font-size:17px; gap:10px; grid-template-columns:22px minmax(0,1fr) 30px; padding:17px 0; } .ac-faq-answer p { font-size:13px; padding-left:32px; padding-right:20px; } }
@media (prefers-reduced-motion:reduce) { .ac-faq *, .ac-faq *::before, .ac-faq *::after { transition:none!important; animation:none!important; } }
